command:
env PYTHONDONTWRITEBYTECODE=1 python3 -c $'import json
from pathlib import Path
root=Path("features/kv-pool-layerwise-reuse/evidence/full-validation-rerun-20260731T064607Z/g0")
pods=json.loads((root/"g0-pods.json").read_text())["items"]
by_app={}
for pod in pods:
    by_app.setdefault(pod["metadata"].get("labels",{}).get("app"),[]).append(pod)
required=("prefill","decode","mooncake-master","proxy")
assert all(len(by_app.get(app,[]))==1 for app in required),{app:len(by_app.get(app,[])) for app in required}
image="docker.io/library/vllm-ascend:kv-pool-layerwise-main-54503ece-a2-14beaf16-20260731T064607Z-r1"
config="sha256:c30f98cf41591582bdb78dde264074a834b68137c5c9254e886cb1347f88bf57"
expected_hostpaths={"/usr/local/dcmi","/usr/local/bin/npu-smi","/usr/local/Ascend/driver/lib64","/usr/local/Ascend/driver/version.info","/etc/ascend_install.info","/home/llm_cache","/usr/bin/hccn_tool","/etc/hccn.conf"}
result={}
for app in required:
    pod=by_app[app][0]
    container=pod["spec"]["containers"][0]
    status=pod["status"]["containerStatuses"][0]
    ready=next((x["status"] for x in pod["status"].get("conditions",[]) if x["type"]=="Ready"),None)
    item={"pod":pod["metadata"]["name"],"node":pod["spec"]["nodeName"],"phase":pod["status"]["phase"],"ready":ready,"image":container["image"],"image_id":status["imageID"],"restart_count":status["restartCount"]}
    assert item["node"]=="n1" and item["phase"]=="Running" and item["restart_count"]==0,item
    if app in {"prefill","decode"}:
        req=container["resources"]["requests"]["huawei.com/Ascend910"]; lim=container["resources"]["limits"]["huawei.com/Ascend910"]
        paths={v["hostPath"]["path"] for v in pod["spec"].get("volumes",[]) if "hostPath" in v}
        env={e["name"]:e.get("value") for e in container.get("env",[]) if "value" in e}
        assert container["image"]==image and item["image_id"]==config and req==lim=="1" and paths==expected_hostpaths
        assert env["PYTHONHASHSEED"]=="0" and "VLLM_VERSION" not in env,(item,env)
    if app=="mooncake-master":
        assert container["image"]==image and item["image_id"]==config and ready=="True",item
    if app=="proxy":
        assert ready=="True",item
    result[app]=item
print(json.dumps({"validated":True,"expected_image":image,"expected_config_id":config,"vllm_lane":"main-verified","vllm_version_override":None,"engine_npu_request_each":1,"engine_hostpaths":sorted(expected_hostpaths),"pods":result},sort_keys=True,indent=2))'
